// Original synthetic acceptance resources, not a substitute for testing the AI provider.
const notes=(understand,teach,help,check)=>"UNDERSTAND: "+understand+"\nSAY AND SHOW: "+teach+"\nIF THEY GET STUCK: "+help+"\nCHECK: "+check;
const slide=(kind,heading,body,visual,n)=>({kind,heading,body,visual,notes:notes(...n)});
const sequence=[{phase:"teach",minutes:5},{phase:"model",minutes:7},{phase:"guided",minutes:8},{phase:"independent",minutes:6},{phase:"check",minutes:4}];
const steps=(items)=>({type:"steps",items:items.map(([label,body])=>({label,body}))});
const evidence=(title,prompt,items,context="reading")=>({type:"evidence-quest",context,passage_title:title,prompt,items});
const sort=(prompt,groups,items)=>({type:"sort-quest",prompt,groups,items});
const data=(title,unit,prompt,rows)=>({type:"data-quest",title,unit,prompt,rows:rows.map(([label,value])=>({label,value}))});
export const englishPack={
 title:"Reading detective: uncover what a character feels",subject:"English",year_level:"Year 4",objective:"Infer a character's likely feelings from actions and language; justify interpretations using specific textual evidence.",
 teaching:"An inference is a reasoned interpretation based on clues in a text and relevant knowledge, rather than something directly stated. A character who waits outside a door and hesitates may be nervous, but the text could also support uncertainty or caution. Distinguish the evidence (what the words say) from the inference (what the reader thinks the clues suggest). Model quoting a short phrase and connecting it with because. Do not require every learner to infer the same emotion if their interpretation is supported.",
 sequence,slides:[
 slide("concept","Become a reading detective","A clue is what the text says. An inference is what the clue suggests. We use evidence to explain our ideas.",steps([["Read the clue","The character checked the clock three times."],["Think","Perhaps the character is worried about being late."],["Explain","The repeated checking suggests concern about time."]]),["A clue is explicit information; an inference is a plausible conclusion supported by that information.","Read the example aloud. Say: ‘The writer never says worried. I notice three checks of the clock, and connect that action with a possible concern about time. That is an inference.’","If the learner repeats the clue, ask what the repeated action might tell us about the character.","Ask which words are evidence and which words describe an inference. Three checks is evidence; worry is an inference."]),
 slide("example","Follow a clue","Read the short example. How does the writer suggest an emotion without naming it?",steps([["What happened?","At the classroom door, the new pupil gripped a bag tightly."],["Which detail matters?","Gripped a bag tightly"],["Reasoning","The action might suggest nervousness, although other explanations are possible."]]),["Actions and word choice can provide evidence for feelings, but an action alone is rarely conclusive.","Reveal the first card and invite a prediction. Reveal the phrase ‘gripped a bag tightly’. Explain how holding something tightly can suggest tension. Reveal the reasoning and ask whether another interpretation might fit.","Use a physical demonstration of relaxed and tense hands. Clarify that this is a clue, not a universal rule.","Ask for an inference and a supporting detail. Nervousness or tension is plausible if linked to the tight grip."]),
 slide("practice","Case file: the unopened letter","Work together to highlight details that suggest the character is reluctant to open the letter.",evidence("The unopened letter","Highlight the clues that suggest reluctance.",["The character turned the envelope over.","Their hands trembled.","They slid it back into the drawer without opening it.","Outside, a bird sang."]),["Reluctance means hesitation or unwillingness. The actions of delaying and putting the letter away support that interpretation.","Invite the learner to highlight the clues. Say: ‘I notice the envelope is still unopened after being handled. Which other action strengthens the inference that the character is reluctant?’ Discuss the strongest evidence before moving on.","Read each sentence aloud and ask whether it tells us about the letter or merely describes the setting.","Trembling and putting the unopened letter away are strong clues; turning it over may contribute when explained. The bird alone does not establish reluctance."]),
 slide("practice","Sort the clues","Separate directly stated evidence from interpretations. Explain the difference.",sort("Put each card into the correct category.",["Textual evidence","Inference"],["The door creaked.","The character may be afraid.","The character stepped backwards.","The character probably wants to leave.","The character spoke quietly."]),["Evidence reports what the words state. An inference interprets those words and may use language like probably or suggests.","Ask the learner to sort independently, then discuss any uncertain card. Say: ‘Tell me which words the writer actually gives us and which words express an interpretation of those details.’","Underline concrete actions in a sample sentence and contrast them with a possible feeling that has not been named.","Evidence: door creaked, stepped backwards, spoke quietly. Inferences: may be afraid, probably wants to leave. Discuss whether the inferences are well supported."]),
 slide("recap","Solve the final case","Find the strongest clue for anticipation. Explain your interpretation in your own words.",evidence("A surprise at the gate","Highlight clues that support anticipation.",["The character waited at the gate before breakfast.","They checked the road whenever a car approached.","The fence was painted blue.","They kept asking whether the visitor was nearly here."]),["Anticipation means expecting something that may happen. Repeated checking and questions can indicate expectation.","Let the learner choose without prompting. Invite a sentence beginning ‘I think the character is anticipating the visitor because...’ Ask which clue gives the strongest evidence and why.","If needed, ask which actions are connected to the visitor and which describe an unrelated feature.","Checking approaching cars and asking about arrival strongly support anticipation; waiting early may also contribute. Blue paint is not relevant on its own."])
 ],worksheet:[{prompt:"A character rereads an invitation and smiles. What feeling might this suggest? Quote a clue.",answer:"Happiness or anticipation is plausible; smiling or rereading the invitation supports the inference."},{prompt:"Write one evidence statement and one inference from: The character stepped back when the door creaked.",answer:"Evidence: stepped back. Inference: may be startled or cautious; other supported interpretations are possible."},{prompt:"Write two original sentences that suggest a character is impatient without using the word impatient.",answer:"Accept coherent observable clues, such as tapping a foot and repeatedly checking the time."}],
 activities:[{title:"Evidence or inference?",type:"choice",question:"Which phrase is directly stated evidence in ‘The character rubbed their eyes and sighed’?",options:["The character rubbed their eyes","The character felt bored","The character wanted to leave"],answer_key:"The character rubbed their eyes"},{title:"Explain a clue",type:"short",question:"Write an inference from the action ‘The character took a deep breath before knocking’. Explain your reasoning.",options:[],answer_key:null}]
};
export const sciencePack={
 title:"Science investigator: observations, inferences and plant growth",subject:"Science",year_level:"Year 5",objective:"Distinguish observations from inferences and use hypothetical measurements to support a limited conclusion about plant growth.",
 teaching:"An observation describes what is noticed or measured, while an inference is an interpretation of the observation. A yellow leaf is observable; a possible nutrient deficiency is an inference, not a diagnosis. In an investigation, compare measurements taken over the same interval and using the same unit. A controlled comparison changes one factor and holds others as constant as practicable. One small hypothetical dataset illustrates reasoning but does not establish a universal cause. A fair test needs repeat measurements and consideration of other explanations.",
 sequence,slides:[
 slide("concept","Observe before explaining","Observations describe what we see or measure. Inferences suggest why it may be happening.",steps([["Observation","The soil feels dry."],["Inference","The plant may need water."],["Test the idea","Compare plants under controlled conditions."]]),["An observation can be checked by measurement or repeated inspection. An inference interprets that information.","Read the dry soil example. Say: ‘I can describe the soil as dry, but I cannot yet prove why the plant looks unhealthy. I have an idea to investigate, not a confirmed explanation.’","Ask whether we could directly see a nutrient deficiency without further evidence. Contrast a measured fact with a proposed cause.","Ask which statement can be checked directly and which proposes an explanation. Dry soil is observable; needing water is an inference."]),
 slide("example","Make a fair comparison","Imagine measuring plant growth over seven days. Use the same measurement method and compare like with like.",steps([["Question","Does changing the amount of light affect growth?"],["Keep conditions comparable","Same plant type, water, soil and measurement interval."],["Measure","Record change in height in centimetres. Repeat the comparison."]]),["A controlled comparison aims to isolate a factor while reducing differences that could affect the outcome.","Say: ‘If one plant gets more water and more light, I cannot tell which change mattered. We change light while keeping water, soil and plant type comparable, then measure height change.’","Use two imaginary pots and ask the learner to spot any unintended differences before discussing the results.","Ask why changing water and light together makes interpretation difficult. Either variable, or both, could contribute to the result."]),
 slide("practice","Sorting station: evidence and ideas","Classify each statement before proposing a test.",sort("Sort observations and inferences.",["Observation","Inference"],["A leaf is yellow.","The plant may need more light.","The soil feels dry.","The plant could have a nutrient deficiency.","Height increased by 2 cm."]),["Measurements and descriptions are observations, while possible explanations are inferences that require further evidence.","Ask the learner to classify each card and explain one placement. Say: ‘The leaf colour is directly observable. Calling it a nutrient deficiency proposes a cause, which we have not demonstrated.’","Read each statement and ask whether a person could record it directly or would need additional testing to establish it.","Observation: yellow leaf, dry soil, 2 cm height increase. Inference: may need more light or could have a deficiency."]),
 slide("practice","Data lab: compare growth","Hypothetical results: similar plants received the same water and soil for seven days, but different light exposure. Select the two groups that grew most.",data("Hypothetical growth over seven days","cm","Select the two groups with the greatest height increase.",[["Low light",1.2],["Moderate light",3.4],["High light",4.1],["Very high light",2.7]]),["The bars represent height changes in the same unit over the same period. This hypothetical comparison permits a descriptive conclusion, not a universal causal claim.","Ask the learner to compare the numbers independently. Then say: ‘Which two groups grew the most in this dataset? Can we say that increasing light always increases growth?’ Refer to the very high light group.","Point to the common zero baseline and read each number aloud. Compare two bars at a time if necessary.","High light and moderate light have the two greatest increases. Very high light grew less than high light, so more light did not always mean greater growth in these hypothetical results."]),
 slide("recap","Draw a careful conclusion","Choose the evidence that challenges the claim that more light always increases growth.",data("Hypothetical repeat comparison, seven days","cm","Select the two light levels that demonstrate a decrease at the highest level.",[["Low",1.8],["Moderate",3.1],["High",4.3],["Very high",2.5]]),["A conclusion must be limited to the available evidence. The comparison of high and very high light contradicts a simple always-increases claim in this dataset.","Let the learner select two bars independently. Invite them to state both numbers and explain why the difference matters. Discuss repeating the investigation before making wider claims.","Ask which two adjacent exposure levels show a drop rather than an increase, using the labelled bars.","High and very high: 4.3 cm compared with 2.5 cm. Growth was lower in the very high group in this hypothetical comparison."])
 ],worksheet:[{prompt:"Classify: ‘The leaf is brown’ and ‘The plant may have too little water’.",answer:"The first is an observation; the second is an inference."},{prompt:"Why keep the water amount the same when testing the effect of light?",answer:"To reduce water as a competing explanation for differences in growth."},{prompt:"Hypothetical growth: low light 1 cm, moderate 3 cm, high 2 cm. Which group grew most? What can you conclude?",answer:"Moderate grew most in this dataset. It does not prove moderate light is best for all plants."}],
 activities:[{title:"Fair comparison",type:"choice",question:"When investigating the effect of light on height, which factor should be kept comparable between groups?",options:["Light exposure","Amount of water","Measured height increase"],answer_key:"Amount of water"},{title:"Explain the limits",type:"short",question:"Why should one small plant growth comparison be repeated before drawing a general conclusion?",options:[],answer_key:null}]
};
